  /// `callback`: a named callback the author declared.
  RIPPLE_EFFECT_KIND_CALLBACK(1),

  /// `jumped`: the story moved to another board.
  RIPPLE_EFFECT_KIND_JUMPED(2),

  /// `ambience`: the soundscape now in force; NULL for silence.
  RIPPLE_EFFECT_KIND_AMBIENCE(3),

  /// `audio`: what the speaker should do, for the mixer.
  RIPPLE_EFFECT_KIND_AUDIO(4),

  /// `changed`: which stores moved.
  RIPPLE_EFFECT_KIND_CHANGED(5),

  /// `show`: a passage — a Turn; answer with `ripple_session_choose`.
  RIPPLE_EFFECT_KIND_SHOW(6),

  /// `ask`: a form — a Turn; answer with `ripple_session_answer`.
  RIPPLE_EFFECT_KIND_ASK(7),

  /// `hold_ms`: a wait — a Turn; call `ripple_session_elapsed` after it.
  RIPPLE_EFFECT_KIND_HOLD(8),

  /// `ended`: the story is over — a Turn.
  RIPPLE_EFFECT_KIND_ENDED(9),

  /// `failed`: the story could not go on — a Turn.
  RIPPLE_EFFECT_KIND_FAILED(10),

  /// The session stopped — a Turn. Carries nothing.
  RIPPLE_EFFECT_KIND_STOPPED(11),

  /// `permit`: the story has not begun and reads these — a Turn; answer
