    3 => RIPPLE_EFFECT_KIND_AMBIENCE,
    4 => RIPPLE_EFFECT_KIND_AUDIO,
    5 => RIPPLE_EFFECT_KIND_CHANGED,
    6 => RIPPLE_EFFECT_KIND_SHOW,
    7 => RIPPLE_EFFECT_KIND_ASK,
