/// What a line of Python came to.
final class RipplePythonResult extends ffi.Struct {
  external RippleValue value;

  /// What it printed.
  external RippleStr output;

  /// NULL when it finished.
  external ffi.Pointer<RipplePythonFailure> error;
}

/// What a call came to.
enum RippleResult {
  /// It did what it was asked.
  RIPPLE_SUCCESS(0),

  /// A document of the bundle is malformed, or is not there.
  RIPPLE_ERROR_BUNDLE_FORMAT(1),

  /// A document of the bundle is from a version this engine cannot read.
  RIPPLE_ERROR_BUNDLE_VERSION(2),

  /// The bundle needs Python and this is the `no-python` library.
  RIPPLE_ERROR_NEEDS_PYTHON(3),

  /// The verb does not answer the turn the story is on.
  RIPPLE_ERROR_WRONG_TURN(10),

  /// A choice past the offered ones.
  RIPPLE_ERROR_NO_SUCH_CHOICE(11),

  /// A choice the author limited, taken as often as they allowed.
  RIPPLE_ERROR_CHOICE_SPENT(12),

  /// The session has stopped and will not move again.
  RIPPLE_ERROR_STOPPED(13),

  /// Nothing has been asked yet: `ripple_session_start` was not called.
  RIPPLE_ERROR_NOTHING_ASKED(14),

  /// A language the campaign is not readable in.
  RIPPLE_ERROR_UNKNOWN_LOCALE(15),

  /// A reading handed in for a kind the host has not granted; `subject`
  /// is the kind's name.
  RIPPLE_ERROR_NOT_PERMITTED(16),

  /// A reader's stand-in that does not read as one; `subject` is the
  /// kind's name, and the message says why.
  RIPPLE_ERROR_STAND_IN(17),

  /// `ripple_session_begin_countdown` or `ripple_session_expire` on a
  /// passage with no countdown.
  RIPPLE_ERROR_NO_COUNTDOWN(18),

  /// `ripple_session_expire` before `ripple_session_begin_countdown`.
  RIPPLE_ERROR_COUNTDOWN_NOT_BEGUN(19),

  /// A save names a board the campaign no longer has.
  RIPPLE_ERROR_BOARD_GONE(20),

  /// A save names a node the board no longer has.
  RIPPLE_ERROR_NODE_GONE(21),

  /// A NULL handle or pointer, a string that is not UTF-8, a value out of
  /// range. Nothing was done.
  RIPPLE_ERROR_INVALID_ARGUMENT(-1),

  /// The engine panicked — or did earlier, on this handle, which is now
  /// poisoned. Destroy it.
  RIPPLE_ERROR_TRAP(-2);

  final int value;
  const RippleResult(this.value);

  static RippleResult fromValue(int value) => switch (value) {
    0 => RIPPLE_SUCCESS,
    1 => RIPPLE_ERROR_BUNDLE_FORMAT,
    2 => RIPPLE_ERROR_BUNDLE_VERSION,
    3 => RIPPLE_ERROR_NEEDS_PYTHON,
    10 => RIPPLE_ERROR_WRONG_TURN,
    11 => RIPPLE_ERROR_NO_SUCH_CHOICE,
    12 => RIPPLE_ERROR_CHOICE_SPENT,
    13 => RIPPLE_ERROR_STOPPED,
    14 => RIPPLE_ERROR_NOTHING_ASKED,
    15 => RIPPLE_ERROR_UNKNOWN_LOCALE,
    16 => RIPPLE_ERROR_NOT_PERMITTED,
    17 => RIPPLE_ERROR_STAND_IN,
    18 => RIPPLE_ERROR_NO_COUNTDOWN,
    19 => RIPPLE_ERROR_COUNTDOWN_NOT_BEGUN,
    20 => RIPPLE_ERROR_BOARD_GONE,
    21 => RIPPLE_ERROR_NODE_GONE,
    -1 => RIPPLE_ERROR_INVALID_ARGUMENT,
    -2 => RIPPLE_ERROR_TRAP,
    _ => throw ArgumentError('Unknown value for RippleResult: $value'),
  };
}

