final class RippleSession extends ffi.Opaque {}

/// Where a new session begins.
final class RippleSessionConfig extends ffi.Struct {
  /// The board, by index into the manifest's boards — usually
  /// `manifest->entries[0]`.
  @ffi.Uint32()
  external int board;

  /// A node to begin at instead of the board's start; absent for the start.
  external RippleStr entry_node;

  /// The language to read in; absent for the default.
  external RippleStr locale;

  /// The dice: the same seed rolls the same story.
  @ffi.Uint64()
  external int seed;

  /// The bundle digest a save made from this session is stamped with;
  /// absent for none.
  external RippleStr digest;

  external RippleSessionOptions options;
}

/// The engine's budgets and policies. Start from
/// [`ripple_session_options_default`] and change what you mean to.
final class RippleSessionOptions extends ffi.Struct {
  /// Steps a run may take before it is stopped; 0 stops on the first.
  @ffi.Uint32()
  external int step_budget;

  /// Silent jumps between boards before the story is stopped.
  @ffi.Uint32()
  external int silent_jump_limit;

  /// Times a loop may go round; 0 is no ceiling.
  @ffi.Uint32()
  external int loop_limit;

  external RippleScriptLimits script_limits;

  /// A [`RippleUntranslated`].
  @ffi.Uint32()
  external int untranslated;

  /// Whether verbs answer `trace` effects.
  @ffi.Bool()
  external bool trace;

  /// Whether a traced value carries its payload.
  @ffi.Bool()
  external bool trace_payloads;
}

/// A snippet of Python in a passage's prose.
final class RippleSnippet extends ffi.Struct {
  external RippleStr code;

  @ffi.Bool()
  external bool is_inline;
}

/// A timeline of clips a passage plays — what `ripple_mixer_play` takes.
final class RippleSoundscape extends ffi.Struct {
  external RippleStr id;

  external RippleStr name;

  @ffi.Int64()
  external int length;

  @ffi.Bool()
  external bool looping;

  @ffi.Int64()
  external int fade_in;

  @ffi.Int64()
  external int fade_out;

  @ffi.Double()
  external double volume;

  @ffi.Bool()
  external bool tied;

  external ffi.Pointer<RippleTrack> tracks;

  @ffi.Size()
  external int track_count;
}

/// A run of UTF-8, measured. `ptr` is NULL for an absent optional string;
/// an empty present one has a non-NULL `ptr` and `len` 0.
///
/// From the engine it is always NUL-terminated past `len`. From a host it
/// need not be: `len` is read and nothing beyond it.
final class RippleStr extends ffi.Struct {
  external ffi.Pointer<ffi.Char> ptr;

  @ffi.Size()
  external int len;

  static ffi.Pointer<RippleStr> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> ptr,
    required int len,
  }) => $allocator<RippleStr>()
    ..ref.ptr = ptr
    ..ref.len = len;
}

/// A list of strings the engine hands over.
final class RippleStrList extends ffi.Struct {
  external ffi.Pointer<RippleStr> items;

  @ffi.Size()
  external int count;

  static ffi.Pointer<RippleStrList> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<RippleStr> items,
    required int count,
  }) => $allocator<RippleStrList>()
    ..ref.items = items
    ..ref.count = count;
}

/// A value on a wire, as the trace saw it.
final class RippleTraceValue extends ffi.Struct {
  external RippleStr from_node;

  external RippleStr from_port;

  external RippleStr to_node;

  external RippleStr to_port;

  /// A [`RipplePayloadKind`].
  @ffi.Uint32()
  external int payload;

  external RippleValue value;
}

/// One clip on a soundscape's timeline. Times are milliseconds.
final class RippleTrack extends ffi.Struct {
  /// The medium, by index into the manifest's media.
  @ffi.Int64()
  external int media;

  @ffi.Int64()
  external int lane;

  @ffi.Int64()
  external int start;

  @ffi.Int64()
  external int clip_start;

  external RippleOptionalI64 clip_end;

  @ffi.Double()
  external double volume;

  @ffi.Double()
  external double speed;

  @ffi.Int64()
  external int fade_in;

  @ffi.Int64()
  external int fade_out;

  /// A [`RippleTrackMode`].
  @ffi.Uint32()
  external int mode;

  @ffi.Int64()
  external int interval;
}

/// How a track repeats.
enum RippleTrackMode {
  RIPPLE_TRACK_MODE_ONCE(0),
  RIPPLE_TRACK_MODE_LOOPING(1),
  RIPPLE_TRACK_MODE_AUTO(2);

  final int value;
  const RippleTrackMode(this.value);

  static RippleTrackMode fromValue(int value) => switch (value) {
    0 => RIPPLE_TRACK_MODE_ONCE,
    1 => RIPPLE_TRACK_MODE_LOOPING,
    2 => RIPPLE_TRACK_MODE_AUTO,
    _ => throw ArgumentError('Unknown value for RippleTrackMode: $value'),
  };
}

/// The turn a story is on, for [`RippleError::asked`].
enum RippleTurnKind {
  RIPPLE_TURN_KIND_PRESENT(0),
  RIPPLE_TURN_KIND_ASK(1),
  RIPPLE_TURN_KIND_WAIT(2),
  RIPPLE_TURN_KIND_ENDED(3),
  RIPPLE_TURN_KIND_FAILED(4),
  RIPPLE_TURN_KIND_STOPPED(5),
  RIPPLE_TURN_KIND_PERMIT(6);

  final int value;
  const RippleTurnKind(this.value);

  static RippleTurnKind fromValue(int value) => switch (value) {
    0 => RIPPLE_TURN_KIND_PRESENT,
    1 => RIPPLE_TURN_KIND_ASK,
    2 => RIPPLE_TURN_KIND_WAIT,
    3 => RIPPLE_TURN_KIND_ENDED,
    4 => RIPPLE_TURN_KIND_FAILED,
    5 => RIPPLE_TURN_KIND_STOPPED,
    6 => RIPPLE_TURN_KIND_PERMIT,
    _ => throw ArgumentError('Unknown value for RippleTurnKind: $value'),
  };
}

/// How a node's turn finished.
enum RippleTurnOutcome {
  RIPPLE_TURN_OUTCOME_DONE(0),
  RIPPLE_TURN_OUTCOME_FAILED(1);

  final int value;
  const RippleTurnOutcome(this.value);

  static RippleTurnOutcome fromValue(int value) => switch (value) {
    0 => RIPPLE_TURN_OUTCOME_DONE,
    1 => RIPPLE_TURN_OUTCOME_FAILED,
    _ => throw ArgumentError('Unknown value for RippleTurnOutcome: $value'),
  };
}

/// What a passage shows when its text is missing in the reader's language.
enum RippleUntranslated {
  /// The text is empty and the passage names the language.
  RIPPLE_UNTRANSLATED_REPORT(0),

  /// The default language's text, and the passage still names it.
  RIPPLE_UNTRANSLATED_FALL_BACK(1);

  final int value;
  const RippleUntranslated(this.value);

  static RippleUntranslated fromValue(int value) => switch (value) {
    0 => RIPPLE_UNTRANSLATED_REPORT,
    1 => RIPPLE_UNTRANSLATED_FALL_BACK,
    _ => throw ArgumentError('Unknown value for RippleUntranslated: $value'),
  };
}

/// A value: its nodes, the root first. An empty arena is null.
final class RippleValue extends ffi.Struct {
  external ffi.Pointer<RippleValueNode> nodes;

  @ffi.Size()
  external int count;

  static ffi.Pointer<RippleValue> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<RippleValueNode> nodes,
    required int count,
  }) => $allocator<RippleValue>()
    ..ref.nodes = nodes
    ..ref.count = count;
}

/// What a node holds, read by its `kind`.
final class RippleValueData extends ffi.Union {
  @ffi.Bool()
  external bool boolean;

  @ffi.Int64()
  external int integer;

  @ffi.Double()
  external double real;

  external RippleStr text;

  external RippleIndices items;

  external RippleEntries entries;
}

/// One entry of a map: a key, and its value's index into the arena.
final class RippleValueEntry extends ffi.Struct {
  external RippleStr key;

  @ffi.Uint32()
  external int node;
}

/// What a [`RippleValueNode`] holds.
enum RippleValueKind {
  RIPPLE_VALUE_KIND_NULL(0),

  /// `data.boolean`.
  RIPPLE_VALUE_KIND_BOOLEAN(1),

  /// `data.integer`: an Int, 64 bits.
  RIPPLE_VALUE_KIND_INTEGER(2),

  /// `data.real`: a Float.
  RIPPLE_VALUE_KIND_REAL(3),

  /// `data.text`.
  RIPPLE_VALUE_KIND_TEXT(4),

  /// `data.items`: a list, its children by index.
  RIPPLE_VALUE_KIND_ITEMS(5),

  /// `data.entries`: a map, its entries in order.
  RIPPLE_VALUE_KIND_ENTRIES(6);

  final int value;
  const RippleValueKind(this.value);

  static RippleValueKind fromValue(int value) => switch (value) {
    0 => RIPPLE_VALUE_KIND_NULL,
    1 => RIPPLE_VALUE_KIND_BOOLEAN,
    2 => RIPPLE_VALUE_KIND_INTEGER,
    3 => RIPPLE_VALUE_KIND_REAL,
    4 => RIPPLE_VALUE_KIND_TEXT,
    5 => RIPPLE_VALUE_KIND_ITEMS,
    6 => RIPPLE_VALUE_KIND_ENTRIES,
    _ => throw ArgumentError('Unknown value for RippleValueKind: $value'),
  };
}

/// One node of an arena.
final class RippleValueNode extends ffi.Struct {
  /// A [`RippleValueKind`].
  @ffi.Uint32()
  external int kind;

  external RippleValueData data;
}

/// A verb that answers a turn, for [`RippleError::answered`].
enum RippleVerb {
  RIPPLE_VERB_CHOOSE(0),
  RIPPLE_VERB_ANSWER(1),
  RIPPLE_VERB_ELAPSED(2),
  RIPPLE_VERB_BEGIN_COUNTDOWN(3),
  RIPPLE_VERB_EXPIRE(4);

  final int value;
  const RippleVerb(this.value);

  static RippleVerb fromValue(int value) => switch (value) {
    0 => RIPPLE_VERB_CHOOSE,
    1 => RIPPLE_VERB_ANSWER,
    2 => RIPPLE_VERB_ELAPSED,
    3 => RIPPLE_VERB_BEGIN_COUNTDOWN,
    4 => RIPPLE_VERB_EXPIRE,
    _ => throw ArgumentError('Unknown value for RippleVerb: $value'),
  };
}

/// One command for the speaker. Read by `kind`; a field another kind uses
/// is zero.
final class RippleVoiceCommand extends ffi.Struct {
  /// A [`RippleVoiceKind`].
  @ffi.Uint32()
  external int kind;

  /// Open, gain, stop: the voice.
  @ffi.Uint64()
  external int voice;

  /// Open: the medium, by index into the manifest's media.
  @ffi.Uint32()
  external int media;

  @ffi.Uint64()
  external int from_ms;

  /// Absent for the file's end.
  external RippleOptionalU64 to_ms;

  /// Open, gain: on the cubic curve.
  @ffi.Double()
  external double gain;

  @ffi.Double()
  external double rate;

  @ffi.Bool()
  external bool looping;

  @ffi.Uint64()
  external int loop_from_ms;

  /// Open: a [`RippleVoiceRole`].
  @ffi.Uint32()
  external int role;

  /// Open, as a track: its index in the soundscape.
  @ffi.Uint32()
  external int track;
}

/// Commands, in the order they are carried out.
final class RippleVoiceCommands extends ffi.Struct {
  external ffi.Pointer<RippleVoiceCommand> items;

  @ffi.Size()
  external int count;

  static ffi.Pointer<RippleVoiceCommands> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<RippleVoiceCommand> items,
    required int count,
  }) => $allocator<RippleVoiceCommands>()
    ..ref.items = items
    ..ref.count = count;
}

/// What a [`RippleVoiceCommand`] tells the speaker.
enum RippleVoiceKind {
  /// Open `voice` on `media` and play it: from `from_ms` to `to_ms` (or
  /// the file's end), at `gain` and `rate`, looping back to
  /// `loop_from_ms` when `looping`.
  RIPPLE_VOICE_KIND_OPEN(0),

  /// Set `voice`'s gain, smoothed over a few milliseconds.
  RIPPLE_VOICE_KIND_GAIN(1),

  /// Stop `voice` for good. It reports no end.
  RIPPLE_VOICE_KIND_STOP(2),

  /// Hold every voice where it is.
  RIPPLE_VOICE_KIND_PAUSE(3),

  /// Let every voice go on.
  RIPPLE_VOICE_KIND_RESUME(4);

  final int value;
  const RippleVoiceKind(this.value);

  static RippleVoiceKind fromValue(int value) => switch (value) {
    0 => RIPPLE_VOICE_KIND_OPEN,
    1 => RIPPLE_VOICE_KIND_GAIN,
    2 => RIPPLE_VOICE_KIND_STOP,
    3 => RIPPLE_VOICE_KIND_PAUSE,
    4 => RIPPLE_VOICE_KIND_RESUME,
    _ => throw ArgumentError('Unknown value for RippleVoiceKind: $value'),
  };
}

/// Why a voice is open.
enum RippleVoiceRole {
  /// A track of the soundscape playing, `track` its index: a long file,
  /// usually better streamed.
  RIPPLE_VOICE_ROLE_TRACK(0),

  /// A cue: a short sound, better decoded whole and started precisely.
  RIPPLE_VOICE_ROLE_CUE(1);

  final int value;
  const RippleVoiceRole(this.value);

  static RippleVoiceRole fromValue(int value) => switch (value) {
    0 => RIPPLE_VOICE_ROLE_TRACK,
    1 => RIPPLE_VOICE_ROLE_CUE,
    _ => throw ArgumentError('Unknown value for RippleVoiceRole: $value'),
  };
}
